<?php

namespace Flow\Parsoid\Fixer;

use DOMElement;
use DOMNode;
use Flow\Conversion\Utils;
use Flow\Parsoid\Fixer;
use HtmlArmor;
use MediaWiki\Cache\LinkBatch;
use MediaWiki\MediaWikiServices;
use MediaWiki\Title\Title;

/**
 * Parsoid ignores red links. With good reason: redlinks should only be
 * applied when rendering the content, not when it's created.
 *
 * This class updates HTML content from Parsoid with anchors generated by
 * LinkRenderer.  In addition to handling red links, this normalizes
 * relative paths to start with a /, so the HTML renders correctly
 * on any page.
 */
class WikiLinkFixer implements Fixer {
	/**
	 * @var LinkBatch
	 */
	protected $batch;

	/** @var bool Maintenance-only A/B experiment, disabled for ordinary page rendering. */
	private bool $benchmarkReusePreloadedTitles = false;

	/** @var array<string,Title> Resolved targets for the current document only. */
	private array $preloadedTitles = [];

	/** @var Title|null Page context for the per-document target memo. */
	private ?Title $preloadedPageTitle = null;

	/**
	 * Enable or disable the temporary benchmark experiment; reset cached
	 * targets so this service cannot carry them into another measurement.
	 */
	public function setBenchmarkReusePreloadedTitles( bool $reuse ): void {
		$this->benchmarkReusePreloadedTitles = $reuse;
		$this->preloadedTitles = [];
		$this->preloadedPageTitle = null;
	}

	/**
	 * @param LinkBatch $batch
	 */
	public function __construct( LinkBatch $batch ) {
		$this->batch = $batch;
	}

	/**
	 * @return string
	 */
	public function getXPath() {
		return '//a[contains(concat(" ",normalize-space(@rel)," ")," mw:WikiLink ")]';
	}

	/**
	 * Warm MediaWiki's LinkCache before LinkRenderer formats individual anchors.
	 * The title resolution must be identical to apply(), including relative links.
	 *
	 * @param iterable<DOMNode> $nodes
	 * @param Title $pageTitle
	 */
	public function preload( iterable $nodes, Title $pageTitle ): void {
		if ( $this->benchmarkReusePreloadedTitles ) {
			// Scope resolution results to this document and its page context.
			$this->preloadedTitles = [];
			$this->preloadedPageTitle = $pageTitle;
		}
		foreach ( $nodes as $node ) {
			if ( !$node instanceof DOMElement ) {
				continue;
			}
			$href = $node->getAttribute( 'href' );
			if ( $href === '' ) {
				continue;
			}
			$target = Utils::createRelativeTitle( rawurldecode( $href ), $pageTitle );
			if ( $target !== null ) {
				if ( $this->benchmarkReusePreloadedTitles ) {
					$this->preloadedTitles[$href] = $target;
				}
				$this->batch->addObj( $target );
			}
		}
		if ( !$this->batch->isEmpty() ) {
			$this->batch->setCaller( __METHOD__ );
			$this->batch->execute();
			// The service is reused while other messages are rendered. Do not
			// requery earlier titles on a later message.
			$this->batch->setArray( [] );
		}
	}

	/**
	 * Parsoid ignores red links. With good reason: redlinks should only be
	 * applied when rendering the content, not when it's created.
	 *
	 * This method will parse a given content, fetch all of its links & let MW's
	 * LinkRenderer build the link HTML (which will take redlinks into account.)
	 * It will then substitute original link HTML for the one LinkRenderer generated.
	 *
	 * This replaces both existing and non-existent anchors because the relative links
	 * output by parsoid are not usable when output within a subpage.
	 *
	 * @param DOMNode $node
	 * @param Title $title Title to resolve relative links against
	 * @throws \Flow\Exception\WikitextException
	 */
	public function apply( DOMNode $node, Title $title ) {
		if ( !$node instanceof DOMElement ) {
			return;
		}

		$href = $node->getAttribute( 'href' );
		if ( $href === '' ) {
			return;
		}

		// The maintenance A/B variant reuses a Title already resolved during
		// LinkBatch preloading. A different page context or an uncached href
		// must still take the unchanged, safe resolution path.
		$preloaded = $this->benchmarkReusePreloadedTitles &&
			$this->preloadedPageTitle === $title &&
			isset( $this->preloadedTitles[$href] );
		$title = $preloaded ? $this->preloadedTitles[$href] :
			Utils::createRelativeTitle( rawurldecode( $href ), $title );
		if ( $title === null ) {
			return;
		}

		// gather existing link attributes
		$attributes = [];
		foreach ( $node->attributes as $attribute ) {
			$attributes[$attribute->name] = $attribute->value;
		}
		// let MW build link HTML based on Parsoid data
		$html = MediaWikiServices::getInstance()->getLinkRenderer()->makeLink(
			$title,
			new HtmlArmor( Utils::getInnerHtml( $node ) ),
			$attributes
		);
		// create new DOM from this MW-built link
		$replacementNode = Utils::createDOM( $html )
			->getElementsByTagName( 'a' )
			->item( 0 );
		// import MW-built link node into content DOM
		// @phan-suppress-next-line PhanTypeMismatchArgumentNullableInternal
		$replacementNode = $node->ownerDocument->importNode( $replacementNode, true );
		// replace Parsoid link with MW-built link
		$node->parentNode->replaceChild( $replacementNode, $node );
	}
}
